// Golden set, mirrored from evals/golden/leads.json. The labels are human
// judgements and are the thing the rubric is measured against, so they are
// never derived from a rubric output.
const GOLDEN_SET = "revenue-swarm-b2b-v1";
const GOLDEN_VERSION = "1.0.0";

const ICP = JSON.stringify({
  target_size_bands: ["51-200", "201-1000", "1000+"],
  core_use_cases: ["workflow automation", "ai agents", "internal tooling"],
  min_score_for_outreach: 50
});

// evals/rubrics/candidate-2.0.0.json: identical weights, lower tier thresholds.
// The theory under test is that the system is too conservative.
const CANDIDATE_RUBRIC = JSON.stringify({
  version: "2.0.0-candidate",
  seniority: { executive: 12, vp: 11, director: 9, manager: 6, ic: 2, unknown: 0 },
  authority: { decision_maker: 13, influencer: 8, end_user: 3, unknown: 0 },
  budget: { explicit: 20, implied: 12, none: 2, unknown: 0 },
  timeline: { immediate: 15, this_quarter: 12, this_year: 6, no_timeline: 2, unknown: 0 },
  pain: { specific: 10, general: 5, none: 0, unknown: 0 },
  fit: { core: 10, adjacent: 6, out_of_scope: 0, unknown: 0 },
  size_points: { in_target: 20, adjacent: 12, outside: 4, unknown: 0 },
  modifiers: { competitor_mentioned: 4, consumer_email_domain: -8, unsupported_evidence: -10, signal_parse_failure: -15 },
  caps: { unknown_threshold: 4, unknown_cap: 45, out_of_scope_cap: 15, parse_error_cap: 40, unreadable_cap: 45 },
  tiers: { hot: 60, warm: 40, cold: 20 }
});

function sig(o) {
  const base = { seniority: "unknown", decision_authority: "unknown", company_size_band: "unknown", budget_signal: "unknown", timeline: "unknown", pain_specificity: "unknown", use_case_fit: "unknown", competitor_mentioned: false, evidence: [] };
  return JSON.stringify(Object.assign(base, o));
}

const CASES = [
  { case_id: "G01", expected_tier: "HOT", outcome: "won", note: "CFO at an enterprise with an approved budget and an immediate start",
    lead: { email: "cfo@enterprise.example", job_title: "CFO", company_name: "Enterprise Co", message: "Board approved 120k for this, we want to start immediately." },
    signals: { seniority: "executive", decision_authority: "decision_maker", company_size_band: "1000+", budget_signal: "explicit", timeline: "immediate", pain_specificity: "specific", use_case_fit: "core" } },
  { case_id: "G02", expected_tier: "HOT", outcome: "won", note: "VP Engineering, mid-market, budget named, buying this quarter",
    lead: { email: "vpe@midmarket.example", job_title: "VP Engineering", company_name: "Midmarket Ltd", message: "We have 40k allocated and want it running this quarter." },
    signals: { seniority: "vp", decision_authority: "decision_maker", company_size_band: "201-1000", budget_signal: "explicit", timeline: "this_quarter", pain_specificity: "specific", use_case_fit: "core" } },
  { case_id: "G03", expected_tier: "HOT", outcome: "won", note: "Director of Ops, in-band, budget implied rather than stated",
    lead: { email: "ops@inband.example", job_title: "Director of Operations", company_name: "Inband Inc", message: "We know roughly what this costs and have room for it this quarter." },
    signals: { seniority: "director", decision_authority: "influencer", company_size_band: "51-200", budget_signal: "implied", timeline: "this_quarter", pain_specificity: "specific", use_case_fit: "core" } },
  { case_id: "G04", expected_tier: "WARM", outcome: "no_reply", note: "Ops manager, adjacent use case, no figure named",
    lead: { email: "mgr@adjacent.example", job_title: "Operations Manager", company_name: "Adjacent Co", message: "Looking at automating onboarding some time this quarter." },
    signals: { seniority: "manager", decision_authority: "influencer", company_size_band: "51-200", budget_signal: "implied", timeline: "this_quarter", pain_specificity: "general", use_case_fit: "adjacent" } },
  { case_id: "G05", expected_tier: "WARM", outcome: "lost", note: "Right company, right use case, no budget and no urgency",
    lead: { email: "mgr@nobudget.example", job_title: "Engineering Manager", company_name: "Nobudget Corp", message: "Interested in principle, nothing set aside yet, maybe later this year." },
    signals: { seniority: "manager", decision_authority: "influencer", company_size_band: "201-1000", budget_signal: "none", timeline: "this_year", pain_specificity: "general", use_case_fit: "core" } },
  { case_id: "G06", expected_tier: "WARM", outcome: "no_reply", note: "Senior and specific, but a company one band below the ICP",
    lead: { email: "dir@smallco.example", job_title: "Director of Engineering", company_name: "Smallco", message: "Our handoff between support and engineering is the specific problem." },
    signals: { seniority: "director", decision_authority: "influencer", company_size_band: "11-50", budget_signal: "implied", timeline: "this_year", pain_specificity: "specific", use_case_fit: "adjacent" } },
  { case_id: "G07", expected_tier: "COLD", outcome: "no_reply", note: "Individual contributor browsing, nothing behind it",
    lead: { email: "eng@browsing.example", job_title: "Engineer", company_name: "Browsing Co", message: "Just having a look." },
    signals: { seniority: "ic", decision_authority: "end_user", company_size_band: "11-50", budget_signal: "none", timeline: "no_timeline", pain_specificity: "general", use_case_fit: "adjacent" } },
  { case_id: "G08", expected_tier: "COLD", outcome: "no_reply", note: "Very small company, no budget - a human would still keep it in nurture rather than bin it",
    lead: { email: "dev@tiny.example", job_title: "Developer", company_name: "Tiny", message: "Might be relevant for us eventually." },
    signals: { seniority: "ic", decision_authority: "end_user", company_size_band: "1-10", budget_signal: "none", timeline: "this_year", pain_specificity: "none", use_case_fit: "adjacent" } },
  { case_id: "G09", expected_tier: "COLD", outcome: "no_reply", note: "Tiny company but a core use case and a manager asking",
    lead: { email: "mgr@tinycore.example", job_title: "Team Lead", company_name: "Tinycore", message: "We would use this for internal tooling if we had the budget." },
    signals: { seniority: "manager", decision_authority: "end_user", company_size_band: "1-10", budget_signal: "none", timeline: "no_timeline", pain_specificity: "general", use_case_fit: "core" } },
  { case_id: "G10", expected_tier: "DISQUALIFIED", outcome: "lost", note: "Textbook buyer for a product we do not sell",
    lead: { email: "cto@wrongfit.example", job_title: "CTO", company_name: "Wrongfit Plc", message: "We need a payroll platform for 400 staff, budget approved, starting now." },
    signals: { seniority: "executive", decision_authority: "decision_maker", company_size_band: "201-1000", budget_signal: "explicit", timeline: "immediate", pain_specificity: "specific", use_case_fit: "out_of_scope" } },
  { case_id: "G11", expected_tier: "DISQUALIFIED", outcome: "no_reply", note: "A form submission that says nothing at all",
    lead: { email: "someone@empty.example", message: "hi" },
    signals: { pain_specificity: "none" } },
  { case_id: "G12", expected_tier: "HOT", outcome: "won", note: "A strong buyer who happened to use a personal email address",
    lead: { email: "strong.buyer@gmail.com", job_title: "VP Revenue Operations", company_name: "Goodfit Co", message: "We have 30k signed off and need this live immediately." },
    signals: { seniority: "vp", decision_authority: "decision_maker", company_size_band: "51-200", budget_signal: "explicit", timeline: "immediate", pain_specificity: "specific", use_case_fit: "core" } }
];

return CASES.map(function (c) {
  return { json: {
    case_id: c.case_id,
    note: c.note,
    expected_tier: c.expected_tier,
    outcome: c.outcome,
    lead: JSON.stringify(c.lead),
    signals: sig(c.signals),
    icp: ICP,
    candidate_rubric: CANDIDATE_RUBRIC,
    golden_set: GOLDEN_SET,
    golden_version: GOLDEN_VERSION
  } };
});

const rows = $input.all().map(function (i) { return i.json; });
const meta = $("Load Golden Set").first().json;

// Every metric here is arithmetic over labelled rows. No model is asked
// whether the new rubric is better, because that is exactly the question
// a model is worst placed to answer about its own output.
function metrics(prefix) {
  const tierKey = prefix + "_tier";
  const correct = rows.filter(function (r) { return r[tierKey] === r.expected_tier; });
  const predictedHot = rows.filter(function (r) { return r[tierKey] === "HOT"; });
  const labelledHot = rows.filter(function (r) { return r.expected_tier === "HOT"; });
  const truePositives = predictedHot.filter(function (r) { return r.expected_tier === "HOT"; });
  const wonAmongPredictedHot = predictedHot.filter(function (r) { return r.outcome === "won"; });
  function ratio(n, d) { return d === 0 ? null : Math.round((n / d) * 1000) / 1000; }
  return {
    accuracy: ratio(correct.length, rows.length),
    hot_precision: ratio(truePositives.length, predictedHot.length),
    hot_recall: ratio(truePositives.length, labelledHot.length),
    hot_conversion: ratio(wonAmongPredictedHot.length, predictedHot.length),
    predicted_hot: predictedHot.length,
    correct: correct.length
  };
}

const A = metrics("a");
const B = metrics("b");

const disagreements = rows.filter(function (r) { return r.a_tier !== r.expected_tier || r.b_tier !== r.expected_tier; })
  .map(function (r) {
    return {
      case_id: r.case_id,
      note: r.note,
      human_label: r.expected_tier,
      production: r.a_tier + " (" + r.a_score + ")",
      candidate: r.b_tier + " (" + r.b_score + ")",
      outcome: r.outcome
    };
  });

// Promotion gate: a candidate may not regress on any tracked metric, and
// must beat production on at least one. Ties are not promotions.
const TRACKED = ["accuracy", "hot_precision", "hot_recall", "hot_conversion"];
const regressions = [];
const improvements = [];
TRACKED.forEach(function (k) {
  const a = A[k];
  const b = B[k];
  if (a === null || b === null) { return; }
  if (b < a) { regressions.push(k + " " + a + " -> " + b); }
  if (b > a) { improvements.push(k + " " + a + " -> " + b); }
});

const promote = regressions.length === 0 && improvements.length > 0;
let reason;
if (regressions.length) {
  reason = "rejected: " + regressions.length + " regression(s) - " + regressions.join("; ");
} else if (!improvements.length) {
  reason = "rejected: the candidate matches production on every tracked metric, so there is nothing to gain by changing";
} else {
  reason = "promote: " + improvements.join("; ") + ", no regressions";
}

return [{ json: {
  run_id: "eval-" + $execution.id,
  golden_set: meta.golden_set,
  golden_version: meta.golden_version,
  total_cases: rows.length,
  rubric_a: rows.length ? rows[0].a_rubric : "unknown",
  rubric_b: rows.length ? rows[0].b_rubric : "unknown",
  production: A,
  candidate: B,
  regressions: regressions,
  improvements: improvements,
  promote: promote,
  promote_reason: reason,
  disagreements: disagreements,
  cases: rows
} }];

function unwrap(x) { return (x && x.json) ? x.json : x; }
const fx = $("Eval Case Loop").first().json;
const a = unwrap($("Score Under Production").first().json);
const b = unwrap($input.first().json);
return [{ json: {
  case_id: fx.case_id,
  note: fx.note,
  expected_tier: fx.expected_tier,
  outcome: fx.outcome,
  a_score: a.score,
  a_tier: a.tier,
  a_rubric: (a.scoring || {}).rubric_version,
  b_score: b.score,
  b_tier: b.tier,
  b_rubric: (b.scoring || {}).rubric_version,
  latency_ms: (a.latency_ms || 0) + (b.latency_ms || 0)
} }];
